// Capability — many unrelated types can be comparable/runnable
interface Discountable { double priceAfterDiscount(); }

// Closely-related family sharing state + code
abstract class Employee {
    protected String name;          // shared state
    Employee(String name) { this.name = name; }
    String badge() { return "EMP:" + name; } // shared code
    abstract double monthlyPay();   // subclass-specific
}

class Contractor extends Employee implements Discountable {
    double rate;
    Contractor(String n, double rate) { super(n); this.rate = rate; }
    double monthlyPay() { return rate * 160; }
    public double priceAfterDiscount() { return rate * 0.9; }
}
