import java.util.*;
import java.util.stream.*;

List<Integer> nums = List.of(1, 2, 3, 4);

// No terminal -> peek never prints, nothing runs
nums.stream().peek(System.out::println).map(n -> n * 10);

// Terminal collect -> the whole pipeline runs in one pass
